"""Runtime upgrade and model health center for the built-in desktop UI."""

from __future__ import annotations

import contextlib
import sys

from app import ui_extension

_EXTENSION_ID = "ovllm-runtime-health-extension"

# fmt: off
_RUNTIME_HEALTH_CSS = r"""
#runtime-health-modal .modal-card{width:min(1080px,calc(100vw - 24px));max-height:min(900px,calc(100dvh - 24px));overflow:hidden}.rh-head p{margin-top:3px;color:var(--text-3);font-size:10px}.rh-body{min-height:0;overflow:auto;padding:16px 18px 22px;overscroll-behavior:contain}.rh-runtime{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:12px}.rh-runtime span{padding:5px 8px;border:1px solid var(--border);border-radius:999px;background:var(--surface-2);color:var(--text-2);font-size:8.5px}.rh-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.rh-stat{padding:10px 11px;border:1px solid var(--border);border-radius:11px;background:var(--surface-2)}.rh-stat span,.rh-stat strong{display:block}.rh-stat span{color:var(--text-3);font-size:8px;text-transform:uppercase;letter-spacing:.5px}.rh-stat strong{margin-top:4px;color:var(--text-1);font-size:14px}.rh-stat.attention strong{color:var(--amber)}.rh-banner{margin-top:10px;padding:9px 10px;border:1px solid var(--border);border-radius:10px;background:var(--surface-2);color:var(--text-2);font-size:9px;line-height:1.45}.rh-banner.warn{border-color:color-mix(in srgb,var(--amber) 38%,var(--border))}.rh-toolbar{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:16px 0 9px}.rh-toolbar h4{font-size:12px}.rh-toolbar-actions{display:flex;flex-wrap:wrap;gap:7px}.rh-btn{min-height:36px;padding:7px 11px;border:1px solid var(--border);border-radius:9px;background:var(--surface-2);color:var(--text-1);font:inherit;font-size:9.5px;font-weight:700;cursor:pointer}.rh-btn:hover:not(:disabled){border-color:var(--primary);background:var(--surface-3)}.rh-btn.primary{border-color:transparent;background:var(--primary);color:#fff}.rh-btn.warn{color:var(--amber);border-color:color-mix(in srgb,var(--amber) 40%,var(--border))}.rh-btn:disabled{opacity:.48;cursor:not-allowed}.rh-list{display:grid;gap:8px}.rh-row{display:grid;grid-template-columns:minmax(190px,1.25fr) minmax(135px,.8fr) minmax(170px,1fr) minmax(150px,auto);gap:10px;align-items:center;padding:11px 12px;border:1px solid var(--border);border-radius:11px;background:color-mix(in srgb,var(--surface-2) 82%,transparent)}.rh-primary,.rh-cell{min-width:0}.rh-primary strong,.rh-primary span,.rh-cell strong,.rh-cell span{display:block;overflow:hidden;text-overflow:ellipsis}.rh-primary strong{color:var(--text-1);font-size:10.5px;white-space:nowrap}.rh-primary span{margin-top:3px;color:var(--text-3);font-size:8.5px;white-space:nowrap}.rh-cell span{color:var(--text-3);font-size:8px;text-transform:uppercase;letter-spacing:.45px}.rh-cell strong{margin-top:3px;color:var(--text-2);font-size:9px;line-height:1.35}.rh-health.good{color:var(--green)}.rh-health.warn{color:var(--amber)}.rh-health.bad{color:var(--red)}.rh-actions{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:6px}.rh-message{margin-top:11px;padding:9px 10px;border-radius:9px;background:var(--surface-2);color:var(--text-2);font-size:9.5px}.rh-message.error{border:1px solid color-mix(in srgb,var(--red) 40%,var(--border));color:var(--red)}.rh-empty,.rh-loading{display:grid;min-height:160px;place-items:center;padding:18px;border:1px dashed var(--border);border-radius:11px;color:var(--text-3);font-size:9.5px;text-align:center}.rh-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 18px calc(11px + env(safe-area-inset-bottom));border-top:1px solid var(--border);background:var(--surface-1)}.rh-footer-note{max-width:720px;color:var(--text-3);font-size:9px;line-height:1.4}.rh-footer-actions{display:flex;gap:7px}@media(max-width:760px){.rh-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.rh-row{grid-template-columns:minmax(0,1fr) auto}.rh-cell{display:none}.rh-toolbar{align-items:stretch;flex-direction:column}.rh-footer{align-items:stretch;flex-direction:column;padding:10px 12px calc(10px + env(safe-area-inset-bottom))}.rh-footer-actions{display:grid;grid-template-columns:1fr 1fr}.rh-btn{min-height:42px}}@media(max-width:520px){#runtime-health-modal .modal-card{width:calc(100vw - 12px);max-height:calc(100dvh - 12px)}.rh-body{padding:12px}.rh-summary{grid-template-columns:1fr 1fr}}
"""

_RUNTIME_HEALTH_JS = r"""
(() => {
'use strict';
if(window.__ovllmRuntimeHealthInstalled)return;
window.__ovllmRuntimeHealthInstalled=true;
const modal=document.createElement('div');modal.className='modal-overlay hidden';modal.id='runtime-health-modal';modal.setAttribute('aria-hidden','true');
modal.innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="rh-title"><div class="modal-header"><div class="rh-head"><h3 id="rh-title">Runtime upgrade and model health</h3><p>See exactly what an OpenVINO upgrade means for each converted model</p></div><button type="button" class="close-btn" id="rh-close" aria-label="Close model health center">&times;</button></div><div class="rh-body"><div class="rh-runtime" id="rh-runtime"></div><div class="rh-summary" id="rh-summary"></div><div id="rh-banner"></div><div class="rh-toolbar"><h4>Model maintenance</h4><div class="rh-toolbar-actions"><button type="button" class="rh-btn" id="rh-batch-validate">Revalidate eligible</button><button type="button" class="rh-btn warn" id="rh-batch-cache">Rebuild affected caches</button></div></div><div id="rh-content"><div class="rh-loading">Checking conversion provenance and runtime versions...</div></div><div id="rh-message" aria-live="polite"></div></div><div class="rh-footer"><span class="rh-footer-note">Conversion provenance is never rewritten by validation. Cache rebuild clears the shared OpenVINO compiled cache once, then warms selected models. Reconversion remains a per-model action.</span><div class="rh-footer-actions"><button type="button" class="rh-btn" id="rh-refresh">Refresh</button><button type="button" class="rh-btn primary" id="rh-done">Done</button></div></div></div>`;
document.body.appendChild(modal);
const $=selector=>modal.querySelector(selector);const content=$('#rh-content');const summary=$('#rh-summary');const runtime=$('#rh-runtime');const banner=$('#rh-banner');const message=$('#rh-message');let data=null;let controller=null;let returnFocus=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const headers=json=>{let key='';try{key=localStorage.getItem('ovllm.apikey.v1')||''}catch{}return {...(key?{Authorization:`Bearer ${key}`}:{ }),'X-OV-LLM-UI':'1',...(json?{'Content-Type':'application/json'}:{})}};
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...headers(Boolean(options.body)),...(options.headers||{})}});let body={};try{body=await response.json()}catch{}if(!response.ok){const detail=body.detail;throw new Error(typeof detail==='object'?(detail.message||'Runtime maintenance failed.'):detail||`Request failed (${response.status})`)}return body}
function setMessage(text='',error=false){message.innerHTML=text?`<div class="rh-message ${error?'error':''}">${esc(text)}</div>`:''}
function healthKind(status){if(status==='compatible')return'good';if(['incomplete','invalid_metadata','incompatible_definition'].includes(status))return'bad';return'warn'}
function row(item){const health=item.conversion_health||{};const rec=item.recommendation||{};const disabled=!rec.available;const reason=rec.blocked_reason||rec.reason||'';const cache=item.source_cache==='reusable'?'HF cache ready':item.source_cache==='not_found'?'HF cache not local':'HF cache unknown';const validation=item.last_validation?.status==='passed'?'Validated locally':item.last_validation?.status==='failed'?'Last validation failed':cache;const primary=rec.action==='leave_unchanged'?'<span class="rh-btn" aria-disabled="true">No action needed</span>':`<button type="button" class="rh-btn ${rec.action==='reconvert'?'warn':''}" data-rh-action="${esc(rec.action)}" data-model="${esc(item.model_id)}" title="${esc(reason)}" ${disabled?'disabled':''}>${esc(rec.label||rec.action)}</button>`;const leave=item.can_leave_unchanged&&rec.action!=='leave_unchanged'?`<button type="button" class="rh-btn" data-rh-action="leave_unchanged" data-model="${esc(item.model_id)}" title="Acknowledge this warning for the current runtime">Leave unchanged</button>`:'';return `<div class="rh-row"><div class="rh-primary"><strong>${esc(item.name)}</strong><span>${esc(item.model_id)} · ${esc(validation)}</span></div><div class="rh-cell"><span>Conversion health</span><strong class="rh-health ${healthKind(health.status)}" title="${esc(health.details||'')}">${esc(health.label||health.status)}</strong></div><div class="rh-cell"><span>Recommended</span><strong title="${esc(reason)}">${esc(rec.label||'Leave unchanged')}</strong></div><div class="rh-actions">${primary}${leave}</div></div>`}
function countText(value,label){const count=Number(value)||0;return `${count} ${label}`}
function render(){const s=data.summary||{};const r=data.runtime||{};runtime.innerHTML=[['InferBridge',r.application],['OpenVINO',r.openvino],['OpenVINO GenAI',r.openvino_genai]].map(([label,value])=>`<span>${esc(label)} ${esc(value||'not detected')}</span>`).join('');summary.innerHTML=[['Needs attention',s.needs_attention,'attention'],['Revalidate',s.revalidate],['Recompile',s.rebuild_compiled_cache],['Reconvert',s.reconvert]].map(([label,value,kind])=>`<div class="rh-stat ${kind||''}"><span>${esc(label)}</span><strong>${Number(value)||0}</strong></div>`).join('');const maintenance=[countText(s.revalidate,'revalidate'),countText(s.rebuild_compiled_cache,'recompile'),countText(s.reconvert,'reconvert')].join(' · ');if(s.runtime_change_detected){banner.innerHTML=s.unresolved_runtime_changes?`<div class="rh-banner warn">OpenVINO changed since one or more conversions were created. ${Number(s.needs_attention)||0} model(s) currently need maintenance: ${esc(maintenance)}.</div>`:'<div class="rh-banner">OpenVINO changed since conversion, but the affected models have been validated or explicitly left unchanged for this runtime.</div>'}else{banner.innerHTML=`<div class="rh-banner">${Number(s.needs_attention)||0} model(s) currently need maintenance: ${esc(maintenance)}.</div>`}content.innerHTML=(data.models||[]).length?`<div class="rh-list">${data.models.map(row).join('')}</div>`:'<div class="rh-empty">No registered models were found.</div>';const validate=(data.models||[]).filter(item=>item.recommendation?.action==='revalidate'&&item.recommendation?.available).map(item=>item.model_id);const cache=(data.models||[]).filter(item=>item.recommendation?.action==='rebuild_compiled_cache'&&item.recommendation?.available).map(item=>item.model_id);$('#rh-batch-validate').disabled=!validate.length;$('#rh-batch-validate').dataset.models=JSON.stringify(validate);$('#rh-batch-cache').disabled=!cache.length;$('#rh-batch-cache').dataset.models=JSON.stringify(cache)}
async function load(){controller?.abort();controller=new AbortController();content.innerHTML='<div class="rh-loading">Checking conversion provenance and runtime versions...</div>';summary.innerHTML='';runtime.innerHTML='';banner.innerHTML='';setMessage();try{data=await api('/v1/runtime-health',{signal:controller.signal});render()}catch(error){if(error.name==='AbortError')return;content.innerHTML='<div class="rh-empty">Runtime health information is unavailable.</div>';setMessage(error.message||String(error),true)}}
function openHealth(source){returnFocus=source||document.activeElement;modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');$('#rh-close').focus();load()}
function close(){modal.classList.add('hidden');modal.setAttribute('aria-hidden','true');controller?.abort();returnFocus?.focus?.()}
function installEntry(container,label){if(!container||container.querySelector('[data-open-runtime-health]'))return;const button=document.createElement('button');button.type='button';button.className=container.closest('#storage-manager-modal')?'sm-btn':'ml-btn';button.dataset.openRuntimeHealth='1';button.textContent=label;button.addEventListener('click',()=>openHealth(button));container.prepend(button)}
installEntry(document.querySelector('#storage-manager-modal .sm-actions'),'Model health');installEntry(document.querySelector('#model-library-modal .ml-footer-actions'),'Model health');
$('#rh-close').addEventListener('click',close);$('#rh-done').addEventListener('click',close);$('#rh-refresh').addEventListener('click',load);modal.addEventListener('click',event=>{if(event.target===modal)close()});modal.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close()}});
content.addEventListener('click',async event=>{const button=event.target.closest('[data-rh-action]');if(!button||button.disabled)return;const action=button.dataset.rhAction;const modelId=button.dataset.model;let text='Run this maintenance action?';if(action==='rebuild_compiled_cache')text='Clear the shared OpenVINO compiled cache, then compile and validate this model again? Other models will compile again on their next load.';else if(action==='reconvert')text='Reconvert this model? Existing Hugging Face cache will be reused when available, and transactional recovery remains enabled.';else if(action==='leave_unchanged')text='Leave this model unchanged for the current runtime and acknowledge the compatibility warning?';if(!window.confirm(text))return;button.disabled=true;setMessage('Applying model maintenance...');try{const result=await api('/v1/runtime-health/action',{method:'POST',body:JSON.stringify({action,model_id:modelId})});setMessage(result.status==='scheduled'?'Reconversion queued. Progress will continue in the normal model lifecycle.':'Maintenance completed.');await load()}catch(error){setMessage(error.message||String(error),true);button.disabled=false}});
async function batch(action,button){let models=[];try{models=JSON.parse(button.dataset.models||'[]')}catch{}if(!models.length)return;const text=action==='rebuild_compiled_cache'?`Clear the shared compiled cache and warm ${models.length} affected model(s)? All models must be unloaded. Models outside this set will compile again on their next load.`:`Revalidate ${models.length} model(s) sequentially with the current runtime? All models must be unloaded.`;if(!window.confirm(text))return;button.disabled=true;setMessage('Running maintenance batch...');try{const result=await api('/v1/runtime-health/batch',{method:'POST',body:JSON.stringify({action,model_ids:models})});const failures=result.failures?.length||0;setMessage(failures?`Batch completed with ${failures} model(s) still needing attention.`:'Batch completed successfully.',Boolean(failures));await load()}catch(error){setMessage(error.message||String(error),true);button.disabled=false}}
$('#rh-batch-validate').addEventListener('click',event=>batch('revalidate',event.currentTarget));$('#rh-batch-cache').addEventListener('click',event=>batch('rebuild_compiled_cache',event.currentTarget));
})();
"""
# fmt: on


def install_runtime_health_ui_extension() -> None:
    if getattr(ui_extension, "_RUNTIME_HEALTH_UI_EXTENSION_INSTALLED", False):
        return
    previous_inject = ui_extension.inject_multimodal_ui

    def inject_with_runtime_health(html: str) -> str:
        html = previous_inject(html)
        if f'id="{_EXTENSION_ID}"' in html:
            return html
        payload = (
            f'\n<style id="{_EXTENSION_ID}-styles">\n{_RUNTIME_HEALTH_CSS}\n</style>\n'
            f'<script id="{_EXTENSION_ID}">\n{_RUNTIME_HEALTH_JS}\n</script>\n'
        )
        if "</body>" in html:
            return html.replace("</body>", f"{payload}</body>", 1)
        return html + payload

    ui_extension.inject_multimodal_ui = inject_with_runtime_health
    ui_extension._RUNTIME_HEALTH_UI_EXTENSION_INSTALLED = True

    # Match the storage manager's late-install behavior for source-mode tests and
    # unusual import orders where app.server was bound before desktop extensions.
    server = sys.modules.get("app.server")
    if server is not None:
        server.inject_multimodal_ui = inject_with_runtime_health
        cache = getattr(server, "_index_html", None)
        if cache is not None:
            with contextlib.suppress(AttributeError):
                cache.cache_clear()


__all__ = ["install_runtime_health_ui_extension"]
